-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261109180000' and name='home_day_picks')=1 then '예' else '아니오' end as value
union all select 'home day picks RLS on, empty',case when exists(select 1 from pg_class where oid=to_regclass('public.app_home_day_picks') and relrowsecurity) and not exists(select 1 from public.app_home_day_picks) then '예' else '아니오' end
union all select 'home day picks one authenticated owner policy',case when (select count(*) from pg_policy where polrelid=to_regclass('public.app_home_day_picks'))=1 and not exists(select 1 from pg_policy where polrelid=to_regclass('public.app_home_day_picks') and (not polpermissive or not (polroles=array[to_regrole('authenticated')::oid]))) then '예' else '아니오' end
union all select 'home day picks: no anon/service_role, no delete, set columns only',case when not has_any_column_privilege('anon','public.app_home_day_picks','select,insert,update,references') and not has_table_privilege('anon','public.app_home_day_picks','select,insert,update,delete') and not has_any_column_privilege('service_role','public.app_home_day_picks','select,insert,update,references') and has_table_privilege('authenticated','public.app_home_day_picks','select') and not has_table_privilege('authenticated','public.app_home_day_picks','insert,update,delete') and has_column_privilege('authenticated','public.app_home_day_picks','day','insert') and not has_column_privilege('authenticated','public.app_home_day_picks','reads','insert') and has_column_privilege('authenticated','public.app_home_day_picks','reads','update') and not has_column_privilege('authenticated','public.app_home_day_picks','workspace_id','update') then '예' else '아니오' end
union all select 'owner check function present',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_is_workspace_owner(uuid)') and prosecdef) then '예' else '아니오' end
union all select 'workspaces grants policies hash',md5(coalesce((select c.relrowsecurity::text||':'||coalesce(c.relacl::text,'') from pg_class c where c.oid=to_regclass('public.app_workspaces')),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_workspaces')),''));
